// BiVelio Savings Layer: a free wiring check, generated by `bvsala init`.
// It asks a question the layer answers on this machine (2 + 2 * 3), so with the
// layer in place the model is not called and your provider bills nothing for it.
// The saving is `estimated`, always shown apart from measured savings. Open core:
// no keys are needed — with none set, the layer runs in COMMUNITY mode with zero telemetry.
// Delete this file once it says ok.
import { createAgent } from "langchain";
import { savingsAgentMiddleware } from "@bivelio/savings-layer/langchain";

const seen = { calls: 0, avoidedLlm: 0, basis: "" };
const savings = savingsAgentMiddleware({
  // OPEN CORE: no license needed. With no BiVelio keys set, the layer runs free and sends nothing
  // to BiVelio. Savings Cloud (optional): set BIVELIO_LICENSE_KEY and BIVELIO_SERVICE_KEY and usage
  // reaches your dashboard and the license renews itself. A key only adds the cloud, except that with
  // a key trimming of superseded tool results only acts inside a tool loop on Anthropic. A license
  // key that IS set but invalid still fails closed, and with a key the layer
  // needs savings.bivelio.com: 72 hours with no answer from it and every call fails with
  // LicenseError until it answers or you unset the key. With no key there is no such dependency.
  licenseKey: process.env.BIVELIO_LICENSE_KEY || undefined,
  licenseServerUrl: "https://savings.bivelio.com",
  serviceAccountKey: process.env.BIVELIO_SERVICE_KEY || undefined,
  onReport: (report) => {
    seen.calls += 1;
    seen.avoidedLlm = report.calls.avoidedLlm;
    seen.basis = report.cost.basis;
  },
});
const agent = createAgent({ model: "openai:gpt-4o-mini", tools: [], middleware: [savings] });

try {
  const state = await agent.invoke({ messages: [{ role: "user", content: "What is 2 + 2 * 3?" }] });
  const text = state.messages.at(-1)?.text ?? "";
  const ok = text.trim() === "8" && seen.avoidedLlm === 1;
  const line = ok
    ? `ok: the layer answered "8" on this machine without calling the model (basis: ${seen.basis}).`
    : seen.calls === 0
      ? "not ok: the layer did not see the call. It has to go LAST in the list, next to the model."
      : `not ok: the layer saw the call but did not answer it (got ${JSON.stringify(text)}). Send this output to support@bivelio.com.`;
  console.log(line);
  if (!ok) process.exitCode = 1;
} catch (err) {
  const reason = err instanceof Error ? err.message : String(err);
  console.log(`not ok: ${reason}`);
  process.exitCode = 1;
} finally {
  savings.close();
}
